import { readFile, writeFile, mkdir } from "node:fs/promises";
import { fileURLToPath } from "node:url";
const output = new URL("../src/abi/index.ts", import.meta.url);
const names = ["PactPayFinancing", "MockSettlementToken"];
let source =
  "// Generated by blockchain:generate from pinned Foundry artifacts. Do not edit.\n";
for (const name of names) {
  const path = new URL(
    `../../contracts/out/${name}.sol/${name}.json`,
    import.meta.url,
  );
  let artifact;
  try {
    artifact = JSON.parse(await readFile(path, "utf8"));
  } catch {
    throw new Error(
      `Missing contract artifact ${fileURLToPath(path)}; run contracts:build first.`,
    );
  }
  source += `export const ${name === "PactPayFinancing" ? "financingAbi" : "mockTokenAbi"} = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;
}
await mkdir(new URL("../src/abi/", import.meta.url), { recursive: true });
await writeFile(output, source);
console.log("Generated typed PactPay ABIs");
